let cellSize = 50;
let cols, rows;
let layers = 1;
// let bgcolor = "000000".split("-").map((a) => "#" + a);
// let colorScheme = [/* 你刚才贴的全套 colorScheme，这里省略 */];
let layerColors = [];

let seed;


function setup() {
	seed = int(random(999999));
	randomSeed(seed);
	createCanvas(windowWidth, windowHeight);
	angleMode(RADIANS);
	rectMode(CENTER);
	noFill();

	cols = floor(width / cellSize) + 1;
	rows = floor(height / cellSize) + 1;

	background(random(bgcolor));

	for (let i = 0; i < layers; i++) {
		layerColors.push(random(colorScheme).colors);
	}
}

function draw() {
	randomSeed(seed);
	background(str(random(bgcolor)) + "33");

	let t = frameCount * 0.01;

	for (let l = 0; l < layers; l++) {
		let offset = l * 8;
		let colors = layerColors[l];
		strokeWeight(2.2 + l * 1.4);

		for (let i = 0; i < cols; i++) {
			for (let j = 0; j < rows; j++) {
				push();

				let x = i * cellSize + cellSize / 2;
				let y = j * cellSize + cellSize / 2;

				// 🌪️ 湍流流场：根据噪声计算向量角度
				let angle = noise(x * 0.05, y * 0.05, t + l * 10) * TWO_PI * 2;
				let vx = cos(angle);
				let vy = sin(angle);

				// 🌪️ 流动偏移：让图案被流场带动（不是静止）
				let dx = vx * 50;
				let dy = vy * 50;
				translate(x + dx, y + dy);

				// 🌪️ 顺着流场方向旋转
				rotate(angle);

				// 🎯 动态缩放模拟扭动与能量变化
				let n = noise(x * 0.01, y * 0.01, t + l);
				let scalePulse = 0.85 + 0.5 * n;
				scale(scalePulse);

				// 🎨 呼吸式透明 + 颜色变化
				let c = color(random(colors));
				c.setAlpha(180 + 20 * cos(t + x * 0.01 + y * 0.01 + l * 2));
				stroke(c);

				// 🎨 使用云纹或雷纹
				if (random() < 0.6) {
					drawYunWen(cellSize - offset, int(random(2, 5)));
				} else {
					drawLeiWen(cellSize - offset);
				}

				pop();
			}
		}
	}
}


function drawLeiWen(s) {
	noStroke();
	fill(random(random(colorScheme).colors));
	let step = s / 6;
	var x = -s / 2;
	var y = -s / 2;
	circle(x, y, step * random(1, 4));
