	// vertex(x + s - step, y + s - step);
	// vertex(x + s - step, y + step * 2);
	// vertex(x + step * 2, y + step * 2);
	// vertex(x + step * 2, y + s - step * 2);
	// vertex(x + s - step * 2, y + s - step * 2);
	// endShape();
}

function drawYunWen(s, swirlCount = 2) {
	noFill();
	let rMax = s / 2;
	let angleStep = TWO_PI / random(2, 1);
	rotate(frameCount / 10);
	beginShape();
	for (let a = 0; a < swirlCount * TWO_PI; a += angleStep) {
		let r = map(a, 0, swirlCount * TWO_PI, rMax, 5);
		var x = cos(a) * r;
		var y = sin(a) * r;
		curveVertex(x, y);
	}
	endShape();
}

